// Maintenance only: npm ci --prefix js/developer/vendor && node js/developer/vendor/update.mjs
import { build } from 'esbuild';
import { copyFile, mkdir, readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
const root = fileURLToPath(new URL('../../../', import.meta.url));
const modules = path.join(root, 'js/developer/vendor/node_modules');
// CommonJS export-star cannot become static ESM exports. Read the production API explicitly
// so the maintainer's NODE_ENV cannot change the generated module's exports.
const reactExports = Object.keys(require(path.join(modules, 'react/cjs/react.production.js')))
    .filter(name => !name.startsWith('__'));
const manifest = JSON.parse(await readFile(new URL('package.json', import.meta.url)));
async function copy(packageName, files, destination) {
    const target = path.join(root, 'third_party', destination);
    await mkdir(target, { recursive: true });
    const metadata = JSON.parse(await readFile(path.join(modules, packageName, 'package.json')));
    if (manifest.dependencies[packageName] && metadata.version !== manifest.dependencies[packageName])
        throw new Error(`Run npm ci: unexpected ${packageName} version ${metadata.version}`);
    for (const [source, name] of files)
        await copyFile(path.join(modules, packageName, source), path.join(target, name));
    await writeFile(path.join(target, 'VERSION'), `${packageName} ${metadata.version}\n`);
}
await copy('@babel/standalone', [['babel.min.js', 'babel.min.js'], ['LICENSE', 'LICENSE']], 'babel');
await copy('jasmine-core', ['jasmine.js', 'jasmine-html.js', 'jasmine.css', 'boot.js']
    .map(name => [`lib/jasmine-core/${name}`, name]).concat([['images/jasmine_favicon.png', 'jasmine_favicon.png'], ['LICENSE', 'LICENSE']]), 'jasmine');
await copy('fflate', [['esm/browser.js', 'browser.mjs'], ['LICENSE', 'LICENSE']], 'fflate');
await copy('react', [['LICENSE', 'LICENSE']], 'react');
await copy('react-dom', [['LICENSE', 'react-dom-LICENSE']], 'react');
await copy('scheduler', [['LICENSE', 'scheduler-LICENSE']], 'react');
await writeFile(path.join(root, 'third_party/react/VERSION'),
    `react ${manifest.dependencies.react}\nreact-dom ${manifest.dependencies['react-dom']}\nscheduler ${JSON.parse(await readFile(path.join(modules, 'scheduler/package.json'))).version}\nesbuild ${manifest.dependencies.esbuild}\n`);
await build({
    absWorkingDir: path.join(root, 'js/developer/vendor'),
    stdin: {
        contents: `export { default, ${reactExports.join(', ')} } from 'react';
export { createRoot, hydrateRoot } from 'react-dom/client';
export { jsx, jsxs } from 'react/jsx-runtime';`,
        resolveDir: path.join(root, 'js/developer/vendor'),
        sourcefile: 'react-runtime.js',
    },
    outfile: path.join(root, 'third_party/react/runtime.mjs'),
    bundle: true, format: 'esm', platform: 'browser', target: 'es2020',
    minify: true, legalComments: 'inline', charset: 'utf8',
    define: { 'process.env.NODE_ENV': '"production"' },
    banner: { js: `// React and React DOM ${manifest.dependencies.react}; generated by js/developer/vendor/update.mjs.` },
});
